// TestPairingRequests covers the pairing_requests control table (device-
// pairing D6): create/get round-trips the RFC3339Nano stamps verbatim,
// SetPairingStatus drives the lifecycle transitions, an expired-but-pending
// row reads THROUGH with its stored status and past expiry (the store is
// value-agnostic — the pairing service's clock decides expiry on read), and
// unknown ids are wrapped sql.ErrNoRows.
func TestPairingRequests(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)
	created := time.Date(2026, 10, 23, 12, 0, 0, 123456789, time.UTC)

	t.Run("create_get_roundtrip", func(t *testing.T) {
		got, err := s.CreatePairingRequest(ctx, "pair_1", "ABCD2345", created, created.Add(5*time.Minute))
		if err != nil {
			t.Fatalf("CreatePairingRequest: %v", err)
		}
		if got.ID != "pair_1" || got.Code != "ABCD2345" || got.Status != "pending" {
			t.Fatalf("create result = %+v, want id=pair_1 code=ABCD2345 status=pending", got)
		}
		row, err := s.GetPairingRequest(ctx, "pair_1")
		if err != nil {
			t.Fatalf("GetPairingRequest: %v", err)
		}
		if row.Code != "ABCD2345" || row.Status != "pending" {
			t.Fatalf("GetPairingRequest = %+v, want code=ABCD2345 status=pending", row)
		}
		if !row.CreatedAt.Equal(created) || !row.ExpiresAt.Equal(created.Add(5*time.Minute)) {
			t.Fatalf("stamps round-trip broken: created %v (want %v), expires %v (want %v)",
				row.CreatedAt, created, row.ExpiresAt, created.Add(5*time.Minute))
		}
	})

	t.Run("status_transitions", func(t *testing.T) {
		// The CHECK admits every vocabulary value; the store validates no
		// transition graph (that is internal/pairing's job). The cycle ends
		// back on 'pending' so the later subtests see a pending row.
		for _, status := range []string{"approved", "consumed", "denied", "expired", "pending"} {
			if err := s.SetPairingStatus(ctx, "pair_1", status); err != nil {
				t.Fatalf("SetPairingStatus %s: %v", status, err)
			}
			row, err := s.GetPairingRequest(ctx, "pair_1")
			if err != nil {
				t.Fatalf("GetPairingRequest after %s: %v", status, err)
			}
			if row.Status != status {
				t.Fatalf("status = %q, want %q", row.Status, status)
			}
		}
	})

	t.Run("expiry_read_through", func(t *testing.T) {
		// An expired-TTL row still reads back exactly as stored: the store
		// never sweeps or rewrites status — the pairing service's lazy
		// read-through (clock-injected) is what flips pending → expired.
		expired, err := s.CreatePairingRequest(ctx, "pair_dead", "WXYZ6789",
			created.Add(-10*time.Minute), created.Add(-5*time.Minute))
		if err != nil {
			t.Fatalf("CreatePairingRequest expired: %v", err)
		}
		row, err := s.GetPairingRequest(ctx, "pair_dead")
		if err != nil {
			t.Fatalf("GetPairingRequest expired: %v", err)
		}
		if row.Status != "pending" {
			t.Fatalf("expired-TTL row status = %q, want stored 'pending' (store never sweeps)", row.Status)
		}
		if !row.ExpiresAt.Equal(expired.ExpiresAt) || row.ExpiresAt.After(created) {
			t.Fatalf("expires_at = %v, want past stamp %v read through", row.ExpiresAt, expired.ExpiresAt)
		}
	})

	t.Run("list_pending_oldest_first", func(t *testing.T) {
		// pair_dead is expired-TTL but still status-pending: the raw pending
		// list is status-only (the service filters by clock). Order: pair_1
		// (created 12:00) then pair_dead (11:50) — oldest first.
		got, err := s.ListPendingPairings(ctx)
		if err != nil {
			t.Fatalf("ListPendingPairings: %v", err)
		}
		if len(got) != 2 || got[0].ID != "pair_dead" || got[1].ID != "pair_1" {
			t.Fatalf("ListPendingPairings = %v, want [pair_dead pair_1] (oldest first)", ids(got))
		}
	})

	t.Run("unknown_id", func(t *testing.T) {
		if _, err := s.GetPairingRequest(ctx, "pair_nope"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetPairingRequest unknown = %v, want wrapped sql.ErrNoRows", err)
		}
		if err := s.SetPairingStatus(ctx, "pair_nope", "approved"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("SetPairingStatus unknown = %v, want wrapped sql.ErrNoRows", err)
		}
	})

	t.Run("check_rejects_unknown_status", func(t *testing.T) {
		if err := s.SetPairingStatus(ctx, "pair_1", "wild"); err == nil {
			t.Fatalf("SetPairingStatus 'wild' = nil, want CHECK violation")
		}
	})

	t.Run("empty_list_is_non_nil", func(t *testing.T) {
		empty := openStore(t)
		got, err := empty.ListPendingPairings(ctx)
		if err != nil {
			t.Fatalf("ListPendingPairings empty: %v", err)
		}
		if got == nil || len(got) != 0 {
			t.Fatalf("ListPendingPairings empty = %v, want non-nil empty slice", got)
		}
	})
}

// TestDeviceTokens covers the device_tokens credential table (device-pairing
// D4/D6): insert + hash lookup round-trip, the UNIQUE token_hash, listing, and
// delete = revoke (a deleted credential stops resolving; a second delete is
// sql.ErrNoRows).
func TestDeviceTokens(t *testing.T) {
	ctx := context.Background()
	s := openStore(t)
	created := time.Date(2026, 10, 23, 13, 0, 0, 0, time.UTC)
	tok := DeviceToken{ID: "dev_1", TokenHash: "hash-a", Code: "ABCD2345", CreatedAt: created}

	t.Run("insert_lookup_roundtrip", func(t *testing.T) {
		if err := s.InsertDeviceToken(ctx, tok); err != nil {
			t.Fatalf("InsertDeviceToken: %v", err)
		}
		got, err := s.LookupDeviceTokenByHash(ctx, "hash-a")
		if err != nil {
			t.Fatalf("LookupDeviceTokenByHash: %v", err)
		}
		if got.ID != "dev_1" || got.TokenHash != "hash-a" || got.Code != "ABCD2345" || !got.CreatedAt.Equal(created) {
			t.Fatalf("lookup = %+v, want dev_1/hash-a/ABCD2345 with stamp %v", got, created)
		}
	})

	t.Run("hash_unique", func(t *testing.T) {
		dup := DeviceToken{ID: "dev_2", TokenHash: "hash-a", Code: "ABCD2345", CreatedAt: created}
		if err := s.InsertDeviceToken(ctx, dup); err == nil {
			t.Fatalf("InsertDeviceToken duplicate hash = nil, want UNIQUE violation")
		}
	})

	t.Run("list_devices", func(t *testing.T) {
		older := DeviceToken{ID: "dev_0", TokenHash: "hash-0", Code: "AAAA2222", CreatedAt: created.Add(-time.Minute)}
		if err := s.InsertDeviceToken(ctx, older); err != nil {
			t.Fatalf("InsertDeviceToken older: %v", err)
		}
		got, err := s.ListDevices(ctx)
		if err != nil {
			t.Fatalf("ListDevices: %v", err)
		}
		if len(got) != 2 || got[0].ID != "dev_0" || got[1].ID != "dev_1" {
			t.Fatalf("ListDevices = %v, want [dev_0 dev_1] (oldest first)", deviceIDs(got))
		}
	})

	t.Run("delete_revokes", func(t *testing.T) {
		if err := s.DeleteDevice(ctx, "dev_1"); err != nil {
			t.Fatalf("DeleteDevice: %v", err)
		}
		if _, err := s.LookupDeviceTokenByHash(ctx, "hash-a"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("lookup after delete = %v, want sql.ErrNoRows (revoked)", err)
		}
		if err := s.DeleteDevice(ctx, "dev_1"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("DeleteDevice repeat = %v, want sql.ErrNoRows (404 at api)", err)
		}
	})

	t.Run("unknown_hash_is_no_rows", func(t *testing.T) {
		if _, err := s.LookupDeviceTokenByHash(ctx, "hash-none"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("lookup unknown hash = %v, want wrapped sql.ErrNoRows", err)
		}
	})
}

// ids maps pairing rows to their ids for failure messages.
func ids(reqs []PairingRequest) []string {
	out := make([]string, len(reqs))
	for i, r := range reqs {
		out[i] = r.ID
	}
	return out
}

// deviceIDs maps device rows to their ids for failure messages.
func deviceIDs(toks []DeviceToken) []string {
	out := make([]string, len(toks))
	for i, t := range toks {
		out[i] = t.ID
	}
	return out
}
